/** probeMedia against clips generated by real ffmpeg. Skips when no FFmpeg is installed. */
import { realpathSync } from 'node:fs';
import { copyFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { afterAll, beforeAll, describe, expect, it, type TestContext } from 'vitest';
import { ok } from '@taalcut/core';
import {
  createMediaService,
  createDirectJobRunner,
  createMediaJobs,
  mediaToolModule,
  probeMedia,
  probeOutputSchema,
  type MediaContext,
  type ProbeResult,
  type RationalTime,
} from '@taalcut/media';
import { findTestBinaries } from '../helpers/binaries';
import { testToolContext } from '../helpers/tool-context';
import {
  makeFixtures,
  PHONE_TAGS,
  removeFixtures,
  type FixtureName,
  type Fixtures,
} from '../helpers/fixtures';

const found = await findTestBinaries('media probe integration');

describe.skipIf(!found.binaries)(
  `probeMedia with real ffprobe${found.binaries ? '' : ' (no FFmpeg found)'}`,
  () => {
    let ctx: MediaContext;
    let fixtures: Fixtures | undefined;

    beforeAll(async () => {
      ctx = { binaries: found.binaries! };
      fixtures = await makeFixtures(ctx, ['h264', 'hevcHlg', 'rotated', 'vfr', 'audio']);
    });

    afterAll(() => removeFixtures(fixtures));

    async function probeFixture(t: TestContext, name: FixtureName): Promise<ProbeResult> {
      const path = fixtures?.paths[name];
      if (!path) t.skip(`fixture '${name}' unavailable: ${fixtures?.missing[name] ?? 'not made'}`);
      const result = await probeMedia(path!, ctx);
      if (!result.ok) throw new Error(`${result.error.code}: ${result.error.detail ?? ''}`);
      return result.value;
    }

    it('reports the build in use', () => {
      const { ffmpegInfo, ffprobeInfo, source } = found.binaries!;
      expect(ffmpegInfo.version).toMatch(/\S/);
      expect(ffprobeInfo.licence).not.toBe('unknown');
      expect(['env', 'sidecar', 'dev-build', 'path']).toContain(source);
    });

    it('H.264 at 30000/1001: exact rates, times and chapters', async (t) => {
      const probe = await probeFixture(t, 'h264');
      expect(probe.container.formatName).toContain('mp4');
      expect(probe.video).toMatchObject({
        codec: 'h264',
        width: 320,
        height: 240,
        rotation: 0,
        bitDepth: 8,
        isHdr: false,
        hdrFormats: [],
        frameRate: { num: 30000, den: 1001 },
        averageFrameRate: { num: 30000, den: 1001 },
        vfrHint: false,
        frameCount: 60,
      });
      // 60 frames of 1001/30000 s, whatever time base the muxer chose.
      const duration = probe.video!.duration!;
      expect(duration.value * 30000).toBe(60060 * duration.rate);
      expect(probe.audio).toMatchObject({ codec: 'aac', sampleRate: 48000, channels: 1 });
      // The mp4 muxer stores chapters in its own time base, so compare exactly in whole seconds.
      const isSeconds = (t: RationalTime | undefined, seconds: number) =>
        t !== undefined && t.value === seconds * t.rate;
      expect(probe.chapters.map((c) => c.title)).toEqual(['Intro', 'Main']);
      expect(isSeconds(probe.chapters[0]?.start, 0)).toBe(true);
      expect(isSeconds(probe.chapters[0]?.end, 1)).toBe(true);
      expect(isSeconds(probe.chapters[1]?.start, 1)).toBe(true);
      expect(probe.creationTime).toMatch(/^2026-10-01T10:00:00/);
      expect(probe.phone).toBeUndefined();
    });

    it('HEVC 10-bit tagged HLG: HDR flag, transfer and bit depth', async (t) => {
      const probe = await probeFixture(t, 'hevcHlg');
      expect(probe.video).toMatchObject({
        codec: 'hevc',
        bitDepth: 10,
        colour: { transfer: 'arib-std-b67', primaries: 'bt2020', space: 'bt2020nc' },
        isHdr: true,
        hdrFormats: ['hlg'],
        frameRate: { num: 25, den: 1 },
      });
      expect(probe.video?.profile).toMatch(/Main 10/);
    });

    it('rotated phone clip: display matrix and QuickTime metadata', async (t) => {
      const probe = await probeFixture(t, 'rotated');
      expect(probe.video).toMatchObject({
        rotation: 90,
        width: 320,
        height: 240,
        displayWidth: 240,
        displayHeight: 320,
      });
      expect(probe.phone).toEqual({
        make: PHONE_TAGS['com.apple.quicktime.make'],
        model: PHONE_TAGS['com.apple.quicktime.model'],
        software: PHONE_TAGS['com.apple.quicktime.software'],
        creationDate: PHONE_TAGS['com.apple.quicktime.creationdate'],
        location: PHONE_TAGS['com.apple.quicktime.location.ISO6709'],
      });
      expect(probe.creationTime).toBe('2026-10-01T15:30:00+0530');
    });

    it('variable frame rate clip: VFR hint from r_frame_rate vs avg_frame_rate', async (t) => {
      const probe = await probeFixture(t, 'vfr');
      expect(probe.video?.frameRate).toEqual({ num: 30, den: 1 });
      expect(probe.video?.vfrHint).toBe(true);
      expect(probe.video?.frameCount).toBe(40);
    });

    it('audio-only file', async (t) => {
      const probe = await probeFixture(t, 'audio');
      expect(probe.video).toBeUndefined();
      expect(probe.audio).toMatchObject({
        codec: 'aac',
        channels: 2,
        sampleRate: 44100,
        duration: { value: 44100, rate: 44100 },
      });
      expect(probe.streams).toHaveLength(1);
    });

    it('a file that is not media is media.probe_failed with ffprobe stderr', async () => {
      const path = join(fixtures!.dir, 'notes.mp4');
      await writeFile(path, 'not a video');
      const result = await probeMedia(path, ctx);
      expect(!result.ok && result.error).toMatchObject({
        code: 'media.probe_failed',
        params: { name: 'notes.mp4' },
      });
      expect(!result.ok && result.error.detail).toContain(realpathSync(path));
      expect(!result.ok && result.error.detail).toMatch(/Invalid data found|moov atom not found/);
    });

    it('a name that looks like a protocol or an option is still read as a local file', async (t) => {
      const source = fixtures?.paths.audio;
      if (!source) t.skip('audio fixture unavailable');
      for (const name of ['http:clip.m4a', '-y.m4a']) {
        const path = join(fixtures!.dir, name);
        await copyFile(source!, path);
        const result = await probeMedia(path, ctx);
        expect(result.ok && result.value.audio?.codec).toBe('aac');
      }
    });

    it('honours an already-aborted signal', async (t) => {
      const path = fixtures?.paths.h264;
      if (!path) t.skip('h264 fixture unavailable');
      const controller = new AbortController();
      controller.abort();
      const cancelled = await probeMedia(path!, ctx, { signal: controller.signal });
      expect(!cancelled.ok && cancelled.error.code).toBe('media.cancelled');
    });

    it('the media.probe tool runs end to end on a phone clip', async (t) => {
      const path = fixtures?.paths.rotated;
      if (!path) t.skip('rotated fixture unavailable');
      const media = createMediaService({ resolver: { resolve: async () => ok(found.binaries!) } });
      const tool = mediaToolModule({ jobs: createDirectJobRunner(createMediaJobs(media)) }).tools[0]!;
      const toolCtx = testToolContext();
      const result = await tool.run({ path }, toolCtx);
      if (!result.ok) throw new Error(`${result.error.code}: ${result.error.detail ?? ''}`);
      const output = probeOutputSchema.parse(result.value);
      expect(output.summary).toMatchObject({
        file: 'rotated-portrait.mov',
        video: { codec: 'h264', width: 240, height: 320, rotation: 90, fps: 29.97, variableFrameRate: false },
        device: 'Apple iPhone 17 Pro',
      });
      expect(output.details?.bytes).toBeGreaterThan(500);
      expect(toolCtx.progress.at(-1)).toEqual({ fraction: 1 });
    });
  },
);
